#!/usr/bin/env node
/**
 * Build `src/components/terminal/xterm.generated.ts` from the xterm.js package.
 *
 * The terminal of the app is xterm.js in a web view. The web view gets the
 * library as text inside its page, not from a network: the terminal opens
 * with no connection to the internet, and nothing outside the app can change
 * the code that reads the shell.
 *
 *   node scripts/vendor-terminal.mjs
 *
 * Run it again after an update of `@xterm/xterm` or `@xterm/addon-fit`.
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { resolve } from 'node:path'

const require = createRequire(import.meta.url)
const read = path => readFileSync(require.resolve(path), 'utf8')
const version = name => JSON.parse(readFileSync(require.resolve(`${name}/package.json`), 'utf8')).version

const parts = {
  XTERM_JS: read('@xterm/xterm/lib/xterm.js'),
  XTERM_CSS: read('@xterm/xterm/css/xterm.css'),
  FIT_JS: read('@xterm/addon-fit/lib/addon-fit.js')
}

// A script inside a <script> tag must not hold "</script": it would end the tag.
const safe = text => text.replace(/<\/script/gi, '<\\/script').replace(/\/\/# sourceMappingURL=.*$/gm, '')

const body = Object.entries(parts)
  .map(([name, text]) => `export const ${name}: string = ${JSON.stringify(safe(text))}`)
  .join('\n\n')

const target = resolve(import.meta.dirname, '../src/components/terminal/xterm.generated.ts')

writeFileSync(
  target,
  `// GENERATED by scripts/vendor-terminal.mjs from @xterm/xterm ${version('@xterm/xterm')} and @xterm/addon-fit ${version('@xterm/addon-fit')}. Do not edit by hand.\n\n${body}\n`
)
console.log(`Wrote ${target}`)
